/**
 * Represents a pre-signed URL and necessary fields required for a client to upload
 * a file directly to the cloud storage provider (e.g. Cloudinary, S3).
 */
export interface PresignedUpload {
  /** The URL where the client should send the upload request (e.g. via POST or PUT). */
  uploadUrl: string;
  /** The permanent storage identifier generated by the backend, to be saved in the database. */
  storageKey: string;
  /** How long the upload URL is valid for. */
  expiresInSeconds: number;
  /**
   * Additional fields the client must send as multipart/form-data.
   * If omitted, the client performs a raw PUT to the uploadUrl.
   */
  uploadFields?: Record<string, string>;
}

/**
 * Shared port for handling media and file storage operations across any module.
 */
export interface StoragePort {
  /**
   * Generates authorization for a client to upload a file directly to storage.
   * @param storageKey The unique identifier/path where the file should be stored.
   * @param isPrivate If true, the file should only be accessible via presigned download URLs.
   * @param options Optional constraints to restrict what the client can upload.
   */
  presignUpload(
    storageKey: string,
    isPrivate: boolean,
    options?: {
      /** Maximum allowed file size in bytes */
      maxSizeBytes?: number;
      /** List of allowed file extensions (e.g., ['jpg', 'png', 'pdf']) */
      allowedFormats?: string[];
    },
  ): Promise<PresignedUpload>;

  /**
   * Returns a permanent, public web address for a file.
   * Should only be used for assets that were uploaded with `isPrivate = false`.
   * @param storageKey The unique identifier of the stored file.
   */
  getPublicUrl(storageKey: string): string;

  /**
   * Generates a temporary, signed URL to view or download a private file.
   * @param storageKey The unique identifier of the stored file.
   * @param expiresInSeconds How long the link should remain valid (defaults to 300).
   */
  presignDownload(storageKey: string, expiresInSeconds?: number): Promise<string>;

  /**
   * Deletes a file from the storage provider.
   * @param storageKey The unique identifier of the stored file.
   */
  deleteFile(storageKey: string): Promise<void>;
}
